#include "common.h"
namespace gather {
std::vector<std::string> entries(){return {"add"};}
Input generate(const std::string &entry,uint64_t seed){Input in;in.entry=entry;in.params={{"vlen",65536},{"nnz",8192}};RNG r(seed);auto a=in.add<double>("Ax","f64",65536,"gather");auto b=in.add<double>("Bx","f64",8192,"input");auto i=in.add<int32_t>("Bi","i32",8192,"index");for(int k=0;k<65536;++k)a[k]=int(r.next()%2001)-1000;for(int k=0;k<8192;++k){b[k]=r.next()%100;i[k]=8*k;}in.add<double>("Cx","f64",65536,"output",true);auto bp=in.add<uint32_t>("Bp","u32",2,"index");bp[1]=8192;auto s=in.add<int64_t>("slice","i64",4,"index");s[3]=8192;return in;}
void validate(Input &in){auto n=in.p("vlen",1,10000000),z=in.p("nnz",0,n);finite_values(in.a<double>("Ax","f64",n),n);finite_values(in.a<double>("Bx","f64",z),z);in.a<double>("Cx","f64",n);index_range(in.a<int32_t>("Bi","i32",z),z,n);auto bp=in.a<uint32_t>("Bp","u32",2);require(bp[0]==0&&bp[1]==z,"Bp must be [0,nnz]");auto s=in.a<int64_t>("slice","i64",4);require(s[0]==0&&s[1]==0&&s[2]==0&&s[3]==z,"slice must be [0,0,0,nnz]");roles(in,"Ax","gather");roles(in,"Bx","input");roles(in,"Bi","index");roles(in,"Bp","index");roles(in,"slice","index");roles(in,"Cx","output",true);}
std::unique_ptr<Case> make_case(const Input &in,Platform &p,bool use_rvv){auto c=std::make_unique<Case>(in,p);auto a=c->work.ptr<double>("Ax"),b=c->work.ptr<double>("Bx"),out=c->work.ptr<double>("Cx");auto i=c->work.ptr<int32_t>("Bi");auto bp=c->work.ptr<uint32_t>("Bp");auto s=c->work.ptr<int64_t>("slice");auto n=in.params.at("vlen");auto fn=SELECT(GB_add_full_32,GB_add_full_32_rvv);c->call=[=]{fn(bp,nullptr,i,nullptr,nullptr,nullptr,b,a,out,s,1,1,n,false,false,n,1,8.0);};return c;}
}
